        width="16"
        height="16"
        aria-hidden="true"
      >
        <path
          fill="currentColor"
          d="M12 2C6.47 2 2 6.5 2 12a10 10 0 0 0 10 10 10 10 0 0 0 10-10A10 10 0 0 0 12 2m0 18a8 8 0 0 1-8-8 8 8 0 0 1 8-8 8 8 0 0 1 8 8 8 8 0 0 1-8 8m-1-13v6h2V7zm0 8v2h2v-2z"
        />
      </svg>
      <span>{{ $t(error) }}</span>
    </div>

    <div
      v-else-if="visibleFields.length === 0"
      class="extraction-insights-panel__state"
    >
      <svg
        class="extraction-insights-panel__state-icon"
        viewBox="0 0 24 24"
        width="16"
        height="16"
        aria-hidden="true"
      >
        <path
          fill="currentColor"
          d="M11 9h2V7h-2m1 13c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8m0-18A10 10 0 0 0 2 12a10 10 0 0 0 10 10 10 10 0 0 0 10-10A10 10 0 0 0 12 2m-1 15h2v-6h-2z"
        />
      </svg>
      <span>
        {{
          searchTerm
            ? $t('extraction_insights.no_match')
            : $t('extraction_insights.empty')
        }}
      </span>
    </div>

    <div v-else class="extraction-insights-panel__list">
      <ExtractionFieldCard
