        @delete-rule="onDeleteRule"
      />
    </div>

    <!--
      Cleanup-all confirm dialog. Plain q-dialog instead of $q.dialog so
      we can render the dynamic count + the explicit "winners are kept"
      reassurance ourselves and keep all i18n keys in the template.
    -->
    <q-dialog v-model="cleanupDialogOpen" persistent>
      <q-card style="min-width: 360px; max-width: 440px">
        <q-card-section>
          <div class="text-h6">
            {{ $t('extraction_insights.cleanup.confirm_title') }}
          </div>
          <p class="q-mt-sm q-mb-none">
            {{
              $t('extraction_insights.cleanup.confirm_body', {
                count: cleanupCandidateCount,
                fields: cleanupFieldCount,
              })
