            @click="confirmCleanup"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!--
      Per-rule delete confirm. Same pattern as cleanup but scoped to one
      rule. The card emits the candidate object so we can show the
      rule's display label in the body without re-deriving it here.
    -->
    <q-dialog v-model="deleteDialogOpen" persistent>
      <q-card style="min-width: 320px; max-width: 420px">
        <q-card-section>
          <div class="text-h6">
            {{ $t('extraction_insights.delete.confirm_title') }}
          </div>
          <p class="q-mt-sm q-mb-none">
            {{
              $t('extraction_insights.delete.confirm_body', {
                name: deleteTargetLabel || '—',
              })
            }}
          </p>
        </q-card-section>
        <q-card-actions align="right">
          <q-btn
            v-close-popup
            flat
            no-caps
            :label="$t('cancel')"
            data-test="extraction-insights-delete-cancel"
          />
          <q-btn
            unelevated
            no-caps
            color="negative"
            :loading="deleteBusy"
            :label="$t('delete')"
            data-test="extraction-insights-delete-confirm"
            @click="confirmDelete"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!--
      XML viewer drawer. Mounted lazily — the viewer fetches the raw XML
      via authenticated GET on first open, so we keep it out of the DOM
      until the user actually clicks a chip. q-dialog re-renders on
      :model-value flip which gives EInvoiceXmlViewer a fresh `targetLine`
      watcher trigger after a second click on a different field.
    -->
    <q-dialog v-model="xmlViewerOpen" :maximized="false" full-width>
      <q-card class="extraction-insights-panel__xml-dialog">
        <q-card-section class="row items-center q-pb-none">
          <div class="text-subtitle1">
            {{ $t('extraction_insights.xml_open_viewer') }}
            <span
              v-if="xmlViewerSourceTag"
              class="extraction-insights-panel__xml-dialog-tag"
            >
              {{ xmlViewerSourceTag }}
            </span>
