<script lang="ts">
import { defineComponent, ref, computed, watch, onMounted, onUnmounted } from 'vue';
import { useI18n } from 'vue-i18n';
import { useQuasar } from 'quasar';
import ExtractionFieldCard from 'src/components/document/ExtractionFieldCard.vue';
import EInvoiceXmlViewer from 'src/pages/Components/EInvoiceXmlViewer.vue';
import { useExtractionExplanation } from 'src/composables/useExtractionExplanation';
import ExtractionExplanationApiService from 'src/services/document/ExtractionExplanationApiService';
import type {
  CandidateRule,
  FieldExplanation,
  XmlSource,
} from 'src/types/extractionExplanation';

export default defineComponent({
  name: 'ExtractionInsightsPanel',
  components: { ExtractionFieldCard, EInvoiceXmlViewer },
  props: {
    docId: { type: String, required: true },
  },
  emits: ['close'],
  setup(props, { emit: _emit }) {
    const $q = useQuasar();
    const { t } = useI18n();
    const apiService = new ExtractionExplanationApiService({});
    const { fields, loading, error, subscribe, unsubscribe, refresh } =
      useExtractionExplanation(apiService);

    const searchTerm = ref('');
    /**
     * Sort order for the field list. Defaults to "attention_first":
     * fields with the lowest confidence appear at the top so the
     * panel reads like a checklist of "things to look at". Power
     * users can flip to other modes via the sort dropdown.
     *
     *   attention_first → score ASC (problematic first) — DEFAULT
     *   confident_first → score DESC (best-first sweep view)
     *   field_name      → A→Z by translated/raw label
     *   default         → backend order (doc / extraction order)
     */
    const sortMode = ref<
      'attention_first' | 'confident_first' | 'field_name' | 'default'
    >('attention_first');
    const xmlViewerOpen = ref(false);
    const xmlViewerTargetLine = ref(0);
    const xmlViewerSourceTag = ref('');

    function onOpenXmlViewer(payload: {
      source: XmlSource;
      targetLine: number | null;
    }) {
      xmlViewerSourceTag.value = payload.source?.short_tag || '';
      // Reset to 0 (truthy guard in viewer) when there's no snippet —
      // the viewer just opens at the top instead of jumping to line 1.
      xmlViewerTargetLine.value = payload.targetLine || 0;
      xmlViewerOpen.value = true;
    }

    /**
     * Substring filter — case-insensitive match against the raw
     * field_name (the machine key). The card itself displays the
     * translated business label, but typing "invoice" or "amount"
     * still narrows down because business keys mostly mirror the
     * English term anyway. A future iteration could fuzzy-match
     * against the translated label too — but that needs an i18n
     * lookup per field on every keystroke and is overkill for now.
     */
    /**
     * Field's "score for sorting" — uses the winning candidate's
     * score when present, falls back to final_confidence (which is
     * what the backend already computes for non-trainable fields
     * like ED + AI). Missing → 0 so unscored items sink to the top
     * in attention-first mode (treated as "needs attention").
     */
    function fieldSortScore(field: FieldExplanation): number {
      const winner = field.candidates && field.candidates[0];
      if (winner && typeof winner.score === 'number') return winner.score;
      if (typeof field.final_confidence === 'number') return field.final_confidence;
      return 0;
    }

    const visibleFields = computed(() => {
      const q = searchTerm.value.trim().toLowerCase();
      const filtered = q
        ? fields.value.filter((f) =>
            (f.field_name || '').toLowerCase().includes(q),
          )
        : fields.value.slice();

      switch (sortMode.value) {
        case 'attention_first':
          // Lowest score (or 0 for unscored) bubbles to the top —
          // turns the panel into a "what needs my attention" list.
          return filtered.sort((a, b) => fieldSortScore(a) - fieldSortScore(b));
        case 'confident_first':
          return filtered.sort((a, b) => fieldSortScore(b) - fieldSortScore(a));
        case 'field_name':
          return filtered.sort((a, b) =>
            (a.field_name || '').localeCompare(b.field_name || ''),
          );
        case 'default':
        default:
          // Preserve backend order (= roughly doc / extraction order).
          return filtered;
      }
    });

    function reload() {
      // Manual reload button still works even with SSE — it forces a
      // single GET via the legacy fallback. Useful if the user feels the
      // stream is stuck (edge case during proxy hiccups).
      void refresh();
    }

    // ── Cleanup-all power feature ──────────────────────────────────────
    //
    // The cleanup button surfaces every non-winner candidate across the
    // currently visible fields and posts the rule_ids to the bulk-delete
    // endpoint. Doing the candidate selection client-side keeps the
    // server endpoint schema-free of "score" semantics — the panel
    // already has the same is_winner flags the user is looking at.
    const cleanupBusy = ref(false);
    const cleanupDialogOpen = ref(false);

    const cleanupRuleIds = computed<string[]>(() => {
      const ids: string[] = [];
      for (const field of visibleFields.value) {
        if (!field.candidates || field.candidates.length < 2) continue;
        for (const candidate of field.candidates) {
          if (!candidate.is_winner && candidate.rule_id) {
            ids.push(candidate.rule_id);
          }
        }
      }
      return ids;
    });
    const cleanupCandidateCount = computed(() => cleanupRuleIds.value.length);
    const cleanupFieldCount = computed(() => {
      let count = 0;
      for (const field of visibleFields.value) {
        if (!field.candidates || field.candidates.length < 2) continue;
        if (field.candidates.some((c) => !c.is_winner && c.rule_id)) count++;
      }
      return count;
    });

    function openCleanupDialog() {
      if (cleanupCandidateCount.value === 0) return;
      cleanupDialogOpen.value = true;
    }

    async function confirmCleanup() {
      const ids = cleanupRuleIds.value;
      if (ids.length === 0) {
        cleanupDialogOpen.value = false;
        return;
      }
      cleanupBusy.value = true;
      try {
        const result = await apiService.bulkDeleteRules(ids);
        $q.notify({
          type: 'positive',
          message: t('extraction_insights.cleanup.success', {
            count: result.deleted_count,
          }),
        });
        void refresh();
      } catch (err) {
        $q.notify({
          type: 'negative',
          message: t('extraction_insights.cleanup.error'),
          caption: String(err ?? ''),
        });
      } finally {
        cleanupBusy.value = false;
        cleanupDialogOpen.value = false;
      }
    }

    // ── Per-rule delete power feature ──────────────────────────────────
    const deleteBusy = ref(false);
    const deleteDialogOpen = ref(false);
    const deleteTargetRuleId = ref<string | null>(null);
    const deleteTargetLabel = ref<string>('');

    function onDeleteRule(payload: {
      candidate: CandidateRule;
      label: string;
    }) {
      if (!payload?.candidate?.rule_id) return;
      deleteTargetRuleId.value = payload.candidate.rule_id;
      deleteTargetLabel.value = payload.label || '';
      deleteDialogOpen.value = true;
    }

    async function confirmDelete() {
      const ruleId = deleteTargetRuleId.value;
      if (!ruleId) {
        deleteDialogOpen.value = false;
        return;
      }
      deleteBusy.value = true;
      try {
        await apiService.deleteRule(ruleId);
        $q.notify({
          type: 'positive',
          message: t('extraction_insights.delete.success'),
        });
        void refresh();
      } catch (err) {
        $q.notify({
          type: 'negative',
          message: t('extraction_insights.delete.error'),
          caption: String(err ?? ''),
        });
      } finally {
        deleteBusy.value = false;
        deleteDialogOpen.value = false;
        deleteTargetRuleId.value = null;
        deleteTargetLabel.value = '';
      }
    }

    onMounted(() => {
      // Live SSE subscription. Vue ref updates on every push — no page
      // reload, no router navigation.
      void subscribe(props.docId);
    });

    onUnmounted(() => {
      unsubscribe();
    });

    watch(
      () => props.docId,
      (newId, oldId) => {
        if (newId && newId !== oldId) {
          // Reset filter so a fresh doc starts un-filtered, otherwise
          // a leftover query could hide all of the new doc's fields.
          searchTerm.value = '';
          void subscribe(newId);
        }
      },
    );

    return {
      fields,
      visibleFields,
      searchTerm,
      sortMode,
      loading,
      error,
      reload,
      xmlViewerOpen,
      xmlViewerTargetLine,
      xmlViewerSourceTag,
      onOpenXmlViewer,
      // cleanup-all
      cleanupBusy,
      cleanupDialogOpen,
      cleanupCandidateCount,
      cleanupFieldCount,
      openCleanupDialog,
      confirmCleanup,
      // per-rule delete
      deleteBusy,
      deleteDialogOpen,
      deleteTargetLabel,
      onDeleteRule,
      confirmDelete,
    };
  },
});
</script>

