<template>
  <div class="scrolle-y relative-position full-height back-white q-mx-sm" v-if="currentSidebar == 'activity_stream'" >
    <DocumentLogs :docId="docId" />
  </div>
  <div class="scrolle-y relative-position full-height back-white q-mx-sm" v-if="currentSidebar == approval_history" >
    <ApprovalHistory />
  </div>
  <!--
    Extraction-insights wrapper uses an explicit flex column with
    min-height: 0 so the inner panel's overflow-y works inside the
    sidebar slot. The legacy "scrolle-y full-height" combo on the
    other two sidebars relies on the panel growing to fit content,
    which made the whole document page scroll instead of the panel
    itself. Keeping the other two unchanged minimises regression risk.
  -->
  <div
    class="extraction-insights-host relative-position back-white q-mx-sm"
    v-if="currentSidebar == 'extraction_insights'"
  >
    <ExtractionInsightsPanel :doc-id="docId" @close="$emit('close')" />
  </div>
  <slot :currentSidebar="currentSidebar" />
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import DocumentLogs from 'src/components/DocumentLogs.vue';
import ApprovalHistory from 'src/components/Approval/ApprovalHistory.vue';
import ExtractionInsightsPanel from 'src/components/document/ExtractionInsightsPanel.vue';
import { approval_history } from 'src/constants';

export default defineComponent({
  name: 'SidebarPanel',
  components: {
    DocumentLogs,
    ApprovalHistory,
    ExtractionInsightsPanel,
  },
  props: {
    currentSidebar: {
      type: String,
      required: true,
    },
    docId: {
      type: String,
      required: true,
    },
  },
  emits: ['close'],
  setup() {
    return {
      approval_history,
    };
  },
});
</script>

<style scoped>
/* The sidebar slot itself has no height set by the parent layout, so
 * the host has to constrain it explicitly. 100vh minus the top app
 * bar (~64 px) and the field-validation toolbar/footer (~56 px) gives
 * the panel a deterministic box that overflow-y can clip against —
 * without this, the panel grows to its content and the browser
 * scrolls the whole document page instead. */
.extraction-insights-host {
  display: flex;
  flex-direction: column;
  min-height: 0;
  height: calc(100vh - 120px);
  overflow: hidden;
}

.extraction-insights-host > * {
  flex: 1 1 auto;
  min-height: 0;
}
</style>
