<template>
  <div
    class="extraction-field-card"
    :class="{ 'extraction-field-card--dirty': isDirty }"
  >
    <div class="extraction-field-card__header">
      <div class="extraction-field-card__title">
        <span class="extraction-field-card__name">{{ fieldDisplayLabel }}</span>
        <span v-if="field.extracted_value" class="extraction-field-card__value">
          {{ field.extracted_value }}
        </span>
      </div>
      <div class="extraction-field-card__chips">
        <!--
          Pending-save chip. Inline SVG instead of `icon="mdi:circle-edit-outline"`
          because the MDI bridge regressed again — the user reported the
          icon rendering as a tiny orange dot floating over the chip's
          label text (the same iconify text-fallback bug we hit five
          times during DOCB-12002). Switching to a slot lets us ship
          the SVG directly so it survives any future bundle/cache
          weirdness.
        -->
        <q-chip
          v-if="isDirty"
