            color="primary"
          />
          <ExtractionScoreBar
            :label="$t('extraction_insights.score.weight')"
            :value="candidate.score_breakdown.weight"
            :max="20"
            color="primary"
          />
          <ExtractionScoreBar
            :label="$t('extraction_insights.score.context_pattern')"
