          />
        </template>
        <p v-else class="extraction-field-card__legacy-hint">
          {{ $t('extraction_insights.no_breakdown_legacy') }}
        </p>

        <div v-if="hasPosition(candidate) || candidate.position_match !== 'no_position'" class="extraction-field-card__meta">
          <!--
            Position chip uses an inline SVG crosshair instead of
            mdi:crosshairs-gps — that icon was rendering as a literal
            "#" text-fallback in production (icon-bundle / cache
            issue), which broke the chip layout and made the
            coordinates barely readable. Inline SVG sidesteps the
