          -->
          <span
            v-if="hasPosition(candidate)"
            class="extraction-field-card__position-chip"
          >
            <svg
              class="extraction-field-card__position-chip-icon"
              viewBox="0 0 24 24"
              width="11"
              height="11"
              aria-hidden="true"
            >
              <path
                fill="currentColor"
                d="M12 8c-2.21 0-4 1.79-4 4s1.79 4 4 4 4-1.79 4-4-1.79-4-4-4m8.94 3A8.994 8.994 0 0 0 13 3.06V1h-2v2.06A8.994 8.994 0 0 0 3.06 11H1v2h2.06A8.994 8.994 0 0 0 11 20.94V23h2v-2.06A8.994 8.994 0 0 0 20.94 13H23v-2zM12 19c-3.87 0-7-3.13-7-7s3.13-7 7-7 7 3.13 7 7-3.13 7-7 7"
              />
            </svg>
            <span>{{ positionLabel(candidate) }}</span>
            <q-tooltip>{{ $t('extraction_insights.position') }}</q-tooltip>
          </span>
          <q-chip
            v-if="candidate.position_match === 'different_position'"
            dense
            size="xs"
            color="warning"
            text-color="white"
            :label="$t('extraction_insights.position_different')"
          />
          <q-chip
            v-else-if="candidate.position_match === 'matched'"
            dense
            size="xs"
            color="positive"
            text-color="white"
            :label="$t('extraction_insights.position_matched')"
          />
        </div>

        <div class="extraction-field-card__training">
          <ExtractionWeightHistory
            :history="candidate.weight_history"
            :sample-size="candidate.sample_size"
          />
          <span class="extraction-field-card__training-text">
            <template v-if="hasTraining(candidate)">
              {{
                $t('extraction_insights.saved_times', { count: candidate.sample_size })
              }}
              —
              {{ $t(`extraction_insights.weight.${weightTier(candidate)}`) }}
            </template>
            <template v-else>
              <!--
                "Not yet trained" reads as a contradiction next to a
                "Trained by …" line. Switched to "No usage history yet"
                — what we actually mean is "no save events have
                reinforced this rule yet", which is independent of who
                authored it.
              -->
              {{ $t('extraction_insights.no_usage_history') }}
            </template>
          </span>
        </div>
        <div
          v-if="trainedByLabel(candidate)"
          class="extraction-field-card__trainer"
        >
          <!--
            Inline SVG account-circle so the avatar slot can never
            overlap the leading "T" of "Trained by …" — the q-icon
            variant collapsed onto the text in production because
            mdi:account-circle-outline mis-rendered into a wider
            placeholder glyph.
          -->
          <svg
            class="extraction-field-card__trainer-icon"
            viewBox="0 0 24 24"
            width="14"
            height="14"
            aria-hidden="true"
          >
            <path
              fill="currentColor"
              d="M12 4a4 4 0 0 1 4 4 4 4 0 0 1-4 4 4 4 0 0 1-4-4 4 4 0 0 1 4-4m0 10c4.42 0 8 1.79 8 4v2H4v-2c0-2.21 3.58-4 8-4"
            />
          </svg>
          <span>
            <!--
              Verb switches based on whether the rule has ever been
              reinforced by a save:
                hasTraining = "Trained by X" — usage-validated history
                no training = "Created by X" — author info only
              This kills the "Trained by Pfaudler SYS · Not yet trained"
              contradiction the user flagged.
            -->
            {{
              hasTraining(candidate)
                ? $t('extraction_insights.trained_by')
                : $t('extraction_insights.created_by')
            }}
            <strong>{{ trainedByLabel(candidate) }}</strong>
          </span>
        </div>
      </div>

      <div v-if="field.candidates.length === 0" class="extraction-field-card__empty">
        {{ $t('extraction_insights.no_rule') }}
      </div>
    </template>

    <template v-else>
      <div class="extraction-field-card__non-trainable">
        <!--
          Business users don't read XML. The card header already shows
          the human-readable field label ("Invoice number") and the
          extracted value above; the "From e-invoice" chip top-right
          says the SOURCE in plain language. The link below is a quiet
          escape hatch for power users who actually want to inspect
          the underlying XML — most users will never need it.
        -->
        <button
          v-for="(source, idx) in xmlSources"
          :key="idx"
          type="button"
          class="extraction-field-card__view-source"
          data-test="extraction-field-card-view-source"
          @click="onXmlChipClick(source)"
        >
          <svg
            class="extraction-field-card__view-source-icon"
            viewBox="0 0 24 24"
            width="13"
            height="13"
            aria-hidden="true"
          >
            <path
              fill="currentColor"
              d="M9.5 3A6.5 6.5 0 0 1 16 9.5c0 1.61-.59 3.09-1.56 4.23l.27.27h.79l5 5-1.5 1.5-5-5v-.79l-.27-.27A6.52 6.52 0 0 1 9.5 16 6.5 6.5 0 0 1 3 9.5 6.5 6.5 0 0 1 9.5 3m0 2C7 5 5 7 5 9.5S7 14 9.5 14 14 12 14 9.5 12 5 9.5 5z"
            />
          </svg>
          <span class="extraction-field-card__view-source-label">
            {{ $t('extraction_insights.view_source') }}
          </span>
          <q-tooltip
            anchor="top middle"
            self="bottom middle"
            :offset="[0, 6]"
            max-width="480px"
          >
            <div class="extraction-field-card__xpath-tooltip">
              <strong>{{ $t('extraction_insights.xml_xpath') }}:</strong>
              <code>{{ source.pre_xpath || source.xpath }}</code>
              <template v-if="source.snippet">
                <strong class="extraction-field-card__snippet-heading">
                  {{ $t('extraction_insights.xml_snippet') }}
                </strong>
                <pre
                  class="extraction-field-card__snippet"
                ><span
                  v-for="(line, i) in source.snippet.lines"
                  :key="i"
                  class="extraction-field-card__snippet-line"
                  :class="{
                    'extraction-field-card__snippet-line--target':
                      source.snippet.start_line + i === source.snippet.target_line,
                  }"
                >{{ line }}</span></pre>
              </template>
