<script lang="ts">
import { defineComponent, ref, computed, onMounted, onUnmounted, type PropType } from 'vue';
import ExtractionScoreBar from 'src/components/document/ExtractionScoreBar.vue';
import ExtractionWeightHistory from 'src/components/document/ExtractionWeightHistory.vue';
import { useDocumentStore } from 'src/store/main';
import {
  formatPosition,
  qualitativeWeight,
  type WeightTier,
} from 'src/utils/extraction-score-formatter';
import type {
  CandidateRule,
  FieldExplanation,
  XmlSource,
} from 'src/types/extractionExplanation';

export default defineComponent({
  name: 'ExtractionFieldCard',
  components: { ExtractionScoreBar, ExtractionWeightHistory },
  props: {
    field: {
      type: Object as PropType<FieldExplanation>,
      required: true,
    },
  },
  emits: {
    /** Emitted when the user clicks an XML source chip. The parent
     *  (ExtractionInsightsPanel) opens EInvoiceXmlViewer in a drawer
     *  and scrolls to `target_line`. */
    'open-xml-viewer': (payload: { source: XmlSource; targetLine: number | null }) =>
      payload && typeof payload === 'object',
    /** Emitted when the user clicks the trash icon on a non-winner
     *  candidate. The parent opens a confirm dialog and (on accept)
     *  posts to /fellow_kv_rules/{rule_id}. `label` is pre-resolved
     *  by the card so the dialog can show a human-readable name
     *  without re-deriving translations. */
    'delete-rule': (payload: { candidate: CandidateRule; label: string }) =>
      payload && typeof payload === 'object' && Boolean(payload.candidate?.rule_id),
  },
  setup(props) {
    const documentStore = useDocumentStore();
    // Bump on every `field_value_updated` to force the isDirty computed
    // to re-evaluate (the underlying `checkifFieldChanged` reads from
    // SessionStorage which Vue cannot track natively).
    const dirtyTick = ref(0);

    function bumpDirty() {
      dirtyTick.value += 1;
    }

    onMounted(() => {
      document.addEventListener('field_value_updated', bumpDirty);
    });
    onUnmounted(() => {
      document.removeEventListener('field_value_updated', bumpDirty);
    });

    const isDirty = computed(() => {
      // Read dirtyTick to register a reactive dependency — the actual
      // value is irrelevant. checkifFieldChanged returns true when the
      // current form value differs from the last-saved snapshot.
      void dirtyTick.value;
      const name = props.field.field_name;
      if (!name) return false;
      try {
        return Boolean(documentStore.checkifFieldChanged(name));
      } catch {
        // Edge: store not yet hydrated. Fail closed so we don't show a
        // misleading "Pending save" badge before the form even loaded.
        return false;
      }
    });

    return { isDirty };
  },
  computed: {
    /** Translated business-language label for the field. The backend
     *  emits machine names like "invoice_id" — the field-validation
     *  form already has Tolgee translations for those (top-level keys
     *  in en.json/de.json). When no translation exists we humanise the
     *  snake_case so we never expose the raw key to a business user. */
    fieldDisplayLabel(): string {
      const name = (this.field.field_name || '').trim();
      if (!name) return '';
      const translated = this.$t(name) as string;
      // Tolgee returns the key itself when the lookup misses — only
      // use the translation when it actually changed something.
      if (translated && translated !== name) return translated;
      // Fallback: invoice_id → "Invoice id"
      return name.charAt(0).toUpperCase() + name.slice(1).replace(/_/g, ' ');
    },
    /** Plain-language method label for the badge — backend codes
     *  AI/ED/CALCULATED/FellowKV2 are dev jargon. Map them to keys
     *  business users actually understand ("From e-invoice", etc). */
    methodChipLabel(): string {
      const method = (this.field.extraction_method || '').toUpperCase();
      const keyByMethod: Record<string, string> = {
        AI: 'extraction_insights.method_chip.ai',
        ELECTRONIC_DOCUMENT: 'extraction_insights.method_chip.electronic_document',
        ED: 'extraction_insights.method_chip.electronic_document',
        CALCULATED: 'extraction_insights.method_chip.calculated',
        FELLOWKV2: 'extraction_insights.method_chip.fellowkv2',
        MD: 'extraction_insights.method_chip.fellowkv2',
      };
      const key = keyByMethod[method];
      if (!key) return this.field.extraction_method || '';
      const translated = this.$t(key) as string;
      return translated && translated !== key
        ? translated
        : this.field.extraction_method || '';
    },
    methodChipColor(): string {
      const method = (this.field.extraction_method || '').toUpperCase();
      if (method === 'AI') return 'purple';
      if (method === 'ELECTRONIC_DOCUMENT' || method === 'ED') return 'teal';
      if (method === 'CALCULATED') return 'indigo';
      return 'primary';
    },
    /** Multi-source aware list. Falls back to the deprecated single
     *  `xml_source` for one release while the backend still emits both. */
    xmlSources(): XmlSource[] {
      const list = this.field.xml_sources;
      if (Array.isArray(list) && list.length > 0) return list;
      return this.field.xml_source ? [this.field.xml_source] : [];
    },
    hasXmlSources(): boolean {
      return this.xmlSources.length > 0;
    },
    firstXmlSource(): XmlSource | null {
      return this.xmlSources[0] || null;
    },
  },
  methods: {
    candidateTitle(candidate: CandidateRule): string {
      // Prefer the original training literal — "Invoice #:" left-side label
      // — over the generated regex which is unreadable to users.
      // See doc2-api PR #9343 for the word_left/word_above backend addition.
      if (candidate.word_left) {
        return `"${candidate.word_left}" left-side label`;
      }
      if (candidate.word_above) {
        return `"${candidate.word_above}" above`;
      }
      // Backwards-compat fallback: a label (regex) without the original word —
      // hide the regex itself, just show position context so users see
      // something meaningful instead of \p{L}-noise.
      if (candidate.label_left) return 'Left-side label';
      if (candidate.label_above) return 'Label above';
      if (candidate.label_right) return 'Right-side label';
      if (candidate.label_below) return 'Label below';
      return `Rule ${candidate.rank}`;
    },
    positionLabel(candidate: CandidateRule): string {
      const formatted = formatPosition(candidate.coords);
      return formatted || '—';
    },
    hasPosition(candidate: CandidateRule): boolean {
      return Boolean(formatPosition(candidate.coords));
    },
    /**
     * Detect legacy candidates: extraction happened before Phase 2 deploy
     * so the per-component score breakdown was never persisted. The aggregate
     * score is non-zero but every sub-score is 0 — showing "Label 0/40,
     * Coordinates 0/40" would be misleading because the bars contradict the
     * displayed final score. We hide the bars and show an explanatory hint.
     */
    isLegacyBreakdown(candidate: CandidateRule): boolean {
      const b = candidate.score_breakdown;
      const allZero =
        b.label === 0 &&
        b.coordinates === 0 &&
        b.weight === 0 &&
        b.context_pattern === 0;
      return allZero && candidate.score > 0;
    },
    /**
     * Hide the "Saved 0 times — low weight" line when the rule has never been
     * trained: that text reads like an informative state but really conveys
     * "no data". Show "Not yet trained" instead.
     */
    hasTraining(candidate: CandidateRule): boolean {
      return candidate.sample_size > 0;
    },
    weightTier(candidate: CandidateRule): WeightTier {
      return qualitativeWeight(candidate.current_aggregated_weight);
    },
    /**
     * Display label for the rule trainer. Order of preference:
     *  1. "First Last" if the cached UsersCache has both name parts
     *  2. email
     *  3. null → footer line is hidden (no leakage of "system" or
     *     "unknown" because we have nothing useful to say)
     */
    trainedByLabel(candidate: CandidateRule): string | null {
      if (
        candidate.trained_by_name &&
        candidate.trained_by_name.trim().length > 0
      ) {
        return candidate.trained_by_name;
      }
      if (
        candidate.trained_by_email &&
        candidate.trained_by_email.trim().length > 0
      ) {
        return candidate.trained_by_email;
      }
      return null;
    },
    onXmlChipClick(source: XmlSource): void {
      // Pass the snippet's target_line through so the viewer can scroll
      // to the exact element. Null when the snippet wasn't built (e.g.
      // legacy doc without raw_xml) — the viewer just opens at the top.
      const targetLine = source.snippet ? source.snippet.target_line : null;
      this.$emit('open-xml-viewer', { source, targetLine });
    },
    onDeleteCandidate(candidate: CandidateRule): void {
      // The card already resolves the candidate's display title (rule
      // body or "Position-only rule" fallback). Pass it along so the
      // panel's confirm dialog can render it without re-deriving the
      // same fallback chain.
      this.$emit('delete-rule', {
        candidate,
        label: this.candidateTitle(candidate),
      });
    },
  },
});
</script>

