// Pure formatters for the extraction insights panel. Kept side-effect-free so
// they can be exercised by unit tests without mounting Vue components.

export type WeightTier = 'high' | 'medium' | 'low';

/**
 * Maps a `currentWeight` (0..100) from FellowKVRuleWeight to a qualitative
 * label used in the panel ("Saved 47 times — high weight"). Thresholds match
 * the panel mockup language: above ~70 is "high", 30..70 is "medium",
 * everything else is "low" (including the unset/zero case).
 */
export function qualitativeWeight(weight: number): WeightTier {
  if (!Number.isFinite(weight)) return 'low';
  if (weight > 70) return 'high';
  if (weight >= 30) return 'medium';
  return 'low';
}

/**
 * Renders a coordinate range as `x: 310-420, y: 142` for the position chip.
 * If x0/x1 collapse to the same value we omit the range and show the point.
 */
export function formatPosition(coords: {
  x0?: number | null;
  x1?: number | null;
  y0?: number | null;
  y1?: number | null;
} | null): string {
  if (!coords) return '';
  const { x0, x1, y0 } = coords;
  const xPart =
    typeof x0 === 'number' && typeof x1 === 'number' && x0 !== x1
      ? `x: ${x0}-${x1}`
      : typeof x0 === 'number'
        ? `x: ${x0}`
        : '';
  const yPart = typeof y0 === 'number' ? `y: ${y0}` : '';
  return [xPart, yPart].filter(Boolean).join(', ');
}

export interface WeightDot {
  /** css color name or hex token consumed by the dot component */
  color: 'success' | 'warning' | 'negative' | 'grey';
  /** opacity 0..1 for stacking older samples behind the most recent */
  intensity: number;
}

/**
 * Maps the `lastFiveWeights` array to renderable dots:
 * - positive sample → success (green)
 * - small positive (0..0.5) → warning (amber)
 * - negative penalty → negative (red)
 * - missing slot → grey
 *
 * The dots are returned oldest-first so the UI can render left-to-right with
 * the freshest sample on the right.
 */
export function mapWeightHistoryToDots(
  history: number[] | null | undefined,
  slots = 5,
): WeightDot[] {
  const safe = Array.isArray(history) ? history : [];
  const padded: (number | null)[] = Array(slots).fill(null);
  // Right-align the actual samples — last sample lands in the last slot.
  const start = Math.max(0, slots - safe.length);
  for (let i = 0; i < Math.min(safe.length, slots); i += 1) {
    padded[start + i] = safe[i];
  }

  return padded.map((value, index) => {
    const intensity = 0.4 + (0.6 * (index + 1)) / slots;
    if (value === null || value === undefined) {
      return { color: 'grey', intensity };
    }
    if (value < 0) {
      return { color: 'negative', intensity };
    }
    if (value >= 0.7) {
      return { color: 'success', intensity };
    }
    if (value > 0) {
      return { color: 'warning', intensity };
    }
    return { color: 'grey', intensity };
  });
}
