<template>
  <template v-if="timeLineData.length > 0">
    <q-timeline color="primary">
      <template v-for="(item, index) in timeLineData" :key="index">
        <q-timeline-entry
          :title="getTitle(item)"
          :subtitle="formatDateTimeZone(item.title)"
          :body="item.notes"
          :color="item.color"
        >
          <div class="row items-center no-wrap">
            <div class="row items-center no-wrap status-badge">
              <q-badge
                color="primary"
                text-color="white"
                v-if="item.color == 'primary'"
                :class="[
                  'text-weight-bold',
                  item.notes && item.notes.trim()
                    ? 'badge-with-text'
                    : 'badge-without-text',
                ]"
              >
                {{ $t('approved') }}
              </q-badge>
              <q-badge
                color="negative"
                text-color="white"
                v-if="item.color == 'red'"
                :class="[
                  'text-weight-bold',
                  item.notes && item.notes.trim()
                    ? 'badge-with-text'
                    : 'badge-without-text',
                ]"
              >
                {{ $t('rejected') }}
              </q-badge>
            </div>
          </div>
        </q-timeline-entry>
      </template>
    </q-timeline>
  </template>
  <template v-else>
    <div class="full-width no-approval-history">
      {{ $t('no_approval_history_available') }}
    </div>
  </template>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import { useDocumentStore } from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [dateUtils],

  mounted: function () {
    this.init();
  },

  methods: {
    init() {
      this.initTimeLineData();
    },
    getTitle(item: any) {
      let title = item.user;

      if (!title) {
        return item.group ? String(item.group) : '-';
      }

      if (item.group) {
        title += ' (' + item.group + ')';
      }

      return String(title);
    },
    initTimeLineData() {
      this.timeLineData = [];

      if (
        !this.record.document_approval ||
        Object.entries(this.record.document_approval).length == 0
      ) {
        return;
      }

      const approvalData = JSON.parse(
        JSON.stringify(this.record.document_approval),
      );

      const approvals = [] as any;
      let approvalList = [] as any;

      if (approvalData.approvals && approvalData.approvals.length > 0) {
        for (let approvedData of approvalData.approvals) {
          approvals[approvedData.request_id] = approvedData;
        }
      }

      if (
        approvalData.approval_requests &&
        approvalData.approval_requests.length > 0
      ) {
        approvalData.approval_requests = approvalData.approval_requests.sort(
          (a: any, b: any) => a.priority - b.priority,
        );
        approvalList = approvalData.approval_requests;
      } else {
        approvalList = approvalData.approvals;
      }

      if (!approvalList || approvalList.length == 0) {
        return;
      }

      for (let approvedData of approvalList) {
        let approval = approvedData;
        if (approvedData.request_id) {
          approval = approvals[approvedData.request_id];
        }

        let user = approvedData.assign_to_user;
        let color = 'grey';
        let title = '';
        let notes = '';
        if (approval) {
          user = approval.approved_by_user ?? approval.held_by_user;
          title =
            approval.approved_on ?? approval.rejected_on ?? approval.held_on;
          notes = approval.notes;
          color = 'primary';

          if (approval.rejected_by_user) {
            color = 'red';
            user = approval.rejected_by_user;
          }
        }

        this.timeLineData.push({
          title: title,
          user: user,
          group: approvedData.assign_to_group ?? approvedData.assigned_to_group,
          notes: notes,
          color: color,
        });
      }
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    return {
      record,
      timeLineData: ref([] as any),
    };
  },
});
</script>

